"sol": "from dataclasses import dataclass\n\n@dataclass\nclass Num:\n    valor: int\n\n@dataclass\nclass Var:\n    nombre: str\n\n@dataclass\nclass BinOp:\n    op: str\n    izq: object\n    der: object\n\n@dataclass\nclass Asig:\n    nombre: str\n    expr: object\n\n\ndef evaluar(nodo):\n    match nodo:\n        case Num(valor):\n            return valor\n        case BinOp(op, izq, der):\n            a, b = evaluar(izq), evaluar(der)\n            if op == \"+\": return a + b\n            if op == \"-\": return a - b\n            if op == \"*\": return a * b\n            if op == \"/\": return a / b\n\narbol = BinOp(\"*\", Num(3), BinOp(\"+\", Num(4), Num(25)))   # 3 * (4 + 25)\nprint(arbol)\nprint(evaluar(arbol))",
