"start": "def lexer(texto):\n    tokens, i = [], 0\n    while i < len(texto):\n        c = texto[i]\n        if c.isspace():\n            i += 1\n        elif c.isdigit():\n            j = i\n            while j < len(texto) and texto[j].isdigit():\n                j += 1\n            tokens.append((\"NUM\", int(texto[i:j])))\n            i = j\n        elif c.isalpha() or c == \"_\":\n            j = i\n            while j < len(texto) and (texto[j].isalnum() or texto[j] == \"_\"):\n                j += 1\n            tokens.append((\"NOMBRE\", texto[i:j]))\n            i = j\n        elif c in \"+-*/()=\":\n            tokens.append((\"OP\", c))\n            i += 1\n        else:\n            raise SyntaxError(f\"carácter inesperado {c!r} en la posición {i}\")\n    return tokens\n\n\nfrom dataclasses import dataclass\n\n@dataclass\nclass Num:\n    valor: int\n\n@dataclass\nclass Var:\n    nombre: str\n\n@dataclass\nclass BinOp:\n    op: str\n    izq: object\n    der: object\n\n@dataclass\nclass Asig:\n    nombre: str\n    expr: object\n\n\nclass Parser:\n    def __init__(self, tokens):\n        self.tokens, self.i = tokens, 0\n\n    def mirar(self):\n        return self.tokens[self.i] if self.i < len(self.tokens) else (\"FIN\", \"fin de línea\")\n\n    def comer(self, tipo, valor=None):\n        tok = self.mirar()\n        if tok[0] != tipo or (valor is not None and tok[1] != valor):\n            raise SyntaxError(f\"se esperaba {valor or tipo!r} y llegó {tok[1]!r}\")\n        self.i += 1\n        return tok\n\n    # expr := termino (('+' | '-') termino)*\n    def expr(self):\n        nodo = self.termino()\n        while self.mirar() in ((\"OP\", \"+\"), (\"OP\", \"-\")):\n            op = self.comer(\"OP\")[1]\n            nodo = BinOp(op, nodo, self.termino())\n        return nodo\n\n    # termino := factor (('*' | '/') factor)*\n    def termino(self):\n        nodo = self.factor()\n        while self.mirar() in ((\"OP\", \"*\"), (\"OP\", \"/\")):\n            op = self.comer(\"OP\")[1]\n            nodo = BinOp(op, nodo, self.factor())\n        return nodo\n\n    # factor := NUM | NOMBRE | '(' expr ')'\n    def factor(self):\n        tipo, valor = self.mirar()\n        if tipo == \"NUM\":\n            self.comer(\"NUM\")\n            return Num(valor)\n        if tipo == \"NOMBRE\":\n            self.comer(\"NOMBRE\")\n            return Var(valor)\n        # ← falta el caso '(' expr ')'\n        raise SyntaxError(f\"no esperaba {valor!r}\")\n\n    # sentencia := NOMBRE '=' expr | expr\n    def sentencia(self):\n        if self.mirar()[0] == \"NOMBRE\" and self.tokens[self.i + 1:self.i + 2] == [(\"OP\", \"=\")]:\n            nombre = self.comer(\"NOMBRE\")[1]\n            self.comer(\"OP\", \"=\")\n            return Asig(nombre, self.expr())\n        return self.expr()\n\n\ndef parsear(texto):\n    p = Parser(lexer(texto))\n    arbol = p.sentencia()\n    if p.mirar()[0] != \"FIN\":\n        raise SyntaxError(f\"sobra {p.mirar()[1]!r}\")\n    return arbol\n\n\ndef evaluar(nodo, entorno):\n    match nodo:\n        case Num(valor):\n            return valor\n        case Var(nombre):\n            if nombre not in entorno:\n                raise NameError(f\"variable no definida: {nombre}\")\n            return entorno[nombre]\n        case Asig(nombre, expr):\n            entorno[nombre] = evaluar(expr, entorno)\n            return entorno[nombre]\n        case BinOp(op, izq, der):\n            a, b = evaluar(izq, entorno), evaluar(der, entorno)\n            if op == \"+\": return a + b\n            if op == \"-\": return a - b\n            if op == \"*\": return a * b\n            if op == \"/\": return a / b\n    raise TypeError(f\"no sé evaluar {nodo}\")\n\nfor src in [\"2 + 3 * 4\", \"(2 + 3) * 4\", \"3 * (4 + 25)\"]:\n    print(src, \"=\", evaluar(parsear(src), {}))",
