"start": "from collections import Counter\n\ntexto = \"la casa, las casas y el casero\"\ntokens = list(texto)\n\ndef par_mas_frecuente(tokens):\n    return Counter(zip(tokens, tokens[1:])).most_common(1)[0][0]\n\ndef fusionar(tokens, par):\n    out, i = [], 0\n    while i < len(tokens):\n        if i + 1 < len(tokens) and (tokens[i], tokens[i + 1]) == par:\n            out.append(tokens[i] + tokens[i + 1])\n            i += 2\n        else:\n            out.append(tokens[i])\n            i += 1\n    return out\n\nfor paso in range(1):\n    par = par_mas_frecuente(tokens)\n    tokens = fusionar(tokens, par)\n    print(f\"fusión {paso + 1}: {par[0]!r} + {par[1]!r}\")\nprint(len(tokens), \"tokens:\", tokens)\n",
